#include <stdio.h>

int main(void) {
    int limit = 0;
    int skip = 0;

    if (scanf("%d", &limit) != 1) {
        return 1;
    }
    if (scanf("%d", &skip) != 1) {
        return 1;
    }

    for (int i = 1; i <= limit; i++) {
        if (i == skip) {
            continue;
        }
        printf("%d\n", i);
    }
    printf("跑完喵\n");
    return 0;
}
